/bin/zsh -lc "python -c 'import pandas as pd; from analysis import fit_quadratic_trend; d=pd.read_csv(\"data/a1b_north_america_annual.csv\"); r=fit_quadratic_trend(d,15.0,225.0); print(r[\"coef\"]); print(r[\"std_err\"]); print(r[\"residual_sd\"]); print(type(next(iter(r[\"fitted\"])))) ;
for bad in [(999,999),(15,225)]:
 x=d.iloc[:3] if bad==(15,225) else d
 try: fit_quadratic_trend(x,*bad)
 except ValueError: print(\"ValueError\",bad)
 else: print(\"unexpected success\",bad)'"

